    function ValidateField_aereo_cpf_particip(&$Campos_Crit, &$Campos_Falta, &$Campos_Erros)
    {
        global $teste_validade;
        $hasError = false;
      if (isset($this->Field_no_validate['aereo_cpf_particip'])) {
          return;
      }
      if ($this->nmgp_opcao != "excluir") 
      { 
          if (NM_utf8_strlen($this->aereo_cpf_particip) > 13) 
          { 
              $hasError = true;
              $Campos_Crit .= "ID Part.: " . $this->Ini->Nm_lang['lang_errm_mxch'] . " 13 " . $this->Ini->Nm_lang['lang_errm_nchr']; 
              if (!isset($Campos_Erros['aereo_cpf_particip']))
              {
                  $Campos_Erros['aereo_cpf_particip'] = array();
              }
              $Campos_Erros['aereo_cpf_particip'][] = $this->Ini->Nm_lang['lang_errm_mxch'] . " 13 " . $this->Ini->Nm_lang['lang_errm_nchr'];
              if (!isset($this->NM_ajax_info['errList']['aereo_cpf_particip']) || !is_array($this->NM_ajax_info['errList']['aereo_cpf_particip']))
              {
                  $this->NM_ajax_info['errList']['aereo_cpf_particip'] = array();
              }
              $this->NM_ajax_info['errList']['aereo_cpf_particip'][] = $this->Ini->Nm_lang['lang_errm_mxch'] . " 13 " . $this->Ini->Nm_lang['lang_errm_nchr'];
          } 
      } 
        if ($hasError) {
            global $sc_seq_vert;
            $fieldName = 'aereo_cpf_particip';
            if (isset($sc_seq_vert) && '' != $sc_seq_vert) {
                $fieldName .= $sc_seq_vert;
            }
