              $Campos_Erros['duracao_voo_api'][] = $this->Ini->Nm_lang['lang_errm_ivch'];
              if (!isset($this->NM_ajax_info['errList']['duracao_voo_api']) || !is_array($this->NM_ajax_info['errList']['duracao_voo_api']))
              {
                  $this->NM_ajax_info['errList']['duracao_voo_api'] = array();
              }
              $this->NM_ajax_info['errList']['duracao_voo_api'][] = $this->Ini->Nm_lang['lang_errm_ivch'];
          } 
      } 
        if ($hasError) {
