$aLookup[] = array(form_aereos_rsvp_1_mob_pack_protect_string('Y') => str_replace('<', '&lt;',form_aereos_rsvp_1_mob_pack_protect_string("Sim")));
$aLookup[] = array(form_aereos_rsvp_1_mob_pack_protect_string('N') => str_replace('<', '&lt;',form_aereos_rsvp_1_mob_pack_protect_string("Não")));
$_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['Lookup_enviar_app'][] = 'Y';
$_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['Lookup_enviar_app'][] = 'N';
          $aLookupOrig = $aLookup;
          $sOptComp = "";
          if (isset($this->NM_ajax_info['select_html']['enviar_app']) && !empty($this->NM_ajax_info['select_html']['enviar_app']))
          {
              $sOptComp = str_replace('{SC_100PERC_CLASS_INPUT}', $this->classes_100perc_fields['input'], $this->NM_ajax_info['select_html']['enviar_app']);
          }
