function getTokenApp(){
$_SESSION['scriptcase']['form_aereos_rsvp_1_mob']['contr_erro'] = 'on';
  	
	date_default_timezone_set('America/Sao_Paulo');
	$curl = curl_init();
	
	
	curl_setopt_array($curl, array(
  	CURLOPT_URL => 'https://api.beinvited.com.br/oauth-token',
	CURLOPT_RETURNTRANSFER => true,
  	CURLOPT_ENCODING => '',
  	CURLOPT_MAXREDIRS => 10,
  	CURLOPT_TIMEOUT => 0,
  	CURLOPT_FOLLOWLOCATION => true,
  	CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
  	CURLOPT_CUSTOMREQUEST => 'POST',
  	CURLOPT_POSTFIELDS => 'grant_type=client_credentials&client_id=SEU_CLIENT_ID&client_secret=SEU_CLIENT_SECRET',
  	CURLOPT_HTTPHEADER => array(
    'Content-Type: application/x-www-form-urlencoded'
  	),
	));
	
	$resp = curl_exec($curl);
	curl_close($curl);	
	$response = json_decode($resp, true);
	$token = $response['access_token'];
	$tokenType = $response['token_type'];
	$expiresIn = $response['expires_in'];
	$scope = $response['scope'];
	
	return $token;

$_SESSION['scriptcase']['form_aereos_rsvp_1_mob']['contr_erro'] = 'off';
}


