   function SC_fast_search($in_fields, $arg_search, $data_search)
   {
      $fields = (strpos($in_fields, "SC_all_Cmp") !== false) ? array("SC_all_Cmp") : explode(";", $in_fields);
      $this->NM_case_insensitive = true;
      if (empty($data_search)) 
      {
         unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['dyn_search_and_or']);
         unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['dyn_search_cache']);
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['where_filter']);
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['total']);
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['fast_search']);
          if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['where_detal']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['where_detal'])) 
          {
              $_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['where_filter'] = $_SESSION['sc_session'][$this->Ini->sc_page]['form_aereos_rsvp_1_mob']['where_detal'];
